from pathlib import Path
import json,hashlib,sys
root=Path(__file__).resolve().parents[1]
hold=root/'reports/cache-hold-v5.0.json'  # v4.3 (crate ponds in the path, 7-10 size ramp, bosses 9/19/29)
if hold.exists() and json.loads(hold.read_text()).get('holdCache') and '--bump-cache' not in sys.argv:
 raise SystemExit('Cache is held for the local v5.0 batch. Use --bump-cache intentionally for an approved local change; no files changed.')
unused={'assets/starters/base.png','assets/starters/bloom.png','assets/starters/bloom-hello-pond.jpg','assets/starters/soaking-scene.jpg','assets/power-icons/bloom-face.png','assets/v64/starters/bloom-hello-pond.png','assets/v6/map-painted.jpg'}  # v4.1: illustrated Pond Path removed; file stays on disk (200) for old v4 clients
urls=['./','index.html','style.css','theme-v3.css','starters-v3.css','powers.js','platform.js','config.js','app.js','core.js','rewards.js','profile.js','rewards-v4.css','theme.js','characters.js','audio.js','music.js','layout.js','levels.json','manifest.webmanifest','visuals-v4.js','visuals-v4.css','tutorial.js','power-identity-v4.css','updates.js','build-info.js','home-v41.css','bonus-v42.css','bonus-ui.js','crates.js','crate-levels.json','roles.js','crates-v43.css','fit.js','score.js','leaderboard.js','explain.js','difficulty.js','v50.css']+[str(p.relative_to(root)) for p in sorted((root/'assets').rglob('*')) if p.is_file() and not (p.parent==root/'assets' and p.name.startswith('capy-')) and 'cast' not in p.parts and str(p.relative_to(root)) not in unused]
DISPLAY_VERSION="5.0"
h=hashlib.sha256(Path(__file__).read_bytes())
for u in urls:
 if u=='build-info.js':continue # generated from this same digest; avoid circular hashing
 h.update(u.encode())
 h.update((root/('index.html'if u=='./'else u)).read_bytes())
build=h.hexdigest()[:12]
version='capydoku-v'+DISPLAY_VERSION+'-'+build
(root/'build-info.js').write_text('// Generated with sw.js; labels the code actually imported by this page.\nexport const BUILD=Object.freeze('+json.dumps({'version':DISPLAY_VERSION,'build':build,'cache':version})+');\n')
script=r'''/* Generated by scripts/build-sw.py. Version-affine offline caches; safe automatic page updates. */
const CACHE=VERSION;
const PRECACHE=URLS;
const META=new URL('__capydoku_client_versions__',self.registration.scope).href;
let queue=Promise.resolve(),activationReady=Promise.resolve();
async function readMeta(){await queue.catch(()=>{});const hit=await(await caches.open(CACHE)).match(META);return hit?hit.json():{cache:CACHE,clients:{},previous:[]}}
async function boundMeta(){for(let i=0;i<240;i++){const m=await readMeta();if(m.activatedAt)return m;if(m.activationError)throw Error(m.activationError);await new Promise(r=>setTimeout(r,25))}throw Error('Version bindings are not ready')}
function mutate(fn){queue=queue.catch(()=>{}).then(async()=>{const c=await caches.open(CACHE),hit=await c.match(META),m=hit?await hit.json():{cache:CACHE,clients:{},previous:[]};await fn(m);await c.put(META,new Response(JSON.stringify(m),{headers:{'Content-Type':'application/json'}}))});return queue}
async function cleanup(){const live=new Set((await self.clients.matchAll({type:'window',includeUncontrolled:true})).map(c=>c.id));await mutate(async m=>{for(const id of Object.keys(m.clients))if(!live.has(id))delete m.clients[id];const used=new Set(Object.values(m.clients));m.previous=m.previous.filter(k=>used.has(k));for(const k of await caches.keys())if(k!==CACHE&&k.startsWith('capydoku-')&&!used.has(k)&&(m.knownPrevious||[]).includes(k))await caches.delete(k)})}
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE),responses=await Promise.all(PRECACHE.map(async url=>{const res=await fetch(new Request(url,{cache:'reload'}));if(res.status!==200)throw Error('Precache failed '+url);const cached=res.clone();await res.arrayBuffer();return[url,cached]}));await Promise.all(responses.map(([u,r])=>cache.put(u,r)));await self.skipWaiting()})()));
self.addEventListener('activate',event=>{activationReady=(async()=>{const keys=(await caches.keys()).filter(k=>k.startsWith('capydoku-')&&k!==CACHE),metas=[];for(const k of keys){const r=await(await caches.open(k)).match(META);if(r)try{metas.push(await r.json())}catch{}}metas.sort((a,b)=>(a.activatedAt||0)-(b.activatedAt||0));const inherited=Object.assign({},...metas.map(m=>m.clients||{})),fallback=metas.at(-1)?.cache||keys.at(-1)||CACHE,windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});await mutate(m=>{m.cache=CACHE;m.activatedAt=Date.now();m.knownPrevious=keys;m.previous=keys;m.clients=Object.fromEntries(windows.map(c=>[c.id,keys.includes(inherited[c.id])?inherited[c.id]:fallback]))});await self.clients.claim();await cleanup()})().catch(async error=>{await mutate(m=>{m.activationError=String(error);m.stack=error.stack});throw error});event.waitUntil(activationReady)});
self.addEventListener('message',event=>{if(event.data?.type==='SKIP_WAITING'){event.waitUntil(self.skipWaiting());return}if(event.data?.type==='CAPYDOKU_CLIENT_READY'&&event.source?.id)event.waitUntil((async()=>{await activationReady;const name=event.data.cache,meta=await boundMeta();if(name===CACHE||meta.knownPrevious?.includes(name))await mutate(m=>{m.clients[event.source.id]=name});await cleanup()})())});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const url=new URL(event.request.url);if(url.origin!==self.location.origin)return;
 event.respondWith((async()=>{
  await activationReady;const bound=await boundMeta();
  if(event.request.mode==='navigate'){const id=event.resultingClientId||event.clientId;if(id)await mutate(m=>{m.clients[id]=CACHE});return await(await caches.open(CACHE)).match('index.html')||fetch(event.request)}
  const meta=bound,name=meta.clients[event.clientId]||CACHE,cache=await caches.open(name),hit=await cache.match(event.request,{ignoreSearch:true});
  const range=event.request.headers.get('range');if(hit&&range&&/\.(mp3|ogg)$/.test(url.pathname)){const bytes=await hit.arrayBuffer(),size=bytes.byteLength,m=/^bytes=(\d*)-(\d*)$/.exec(range);if(!m||(!m[1]&&!m[2]))return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});const start=m[1]?Number(m[1]):Math.max(0,size-Number(m[2])),end=m[1]&&m[2]?Math.min(size-1,Number(m[2])):size-1;if(start>=size||end<start)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});const headers=new Headers(hit.headers);headers.set('Content-Range',`bytes ${start}-${end}/${size}`);headers.set('Content-Length',String(end-start+1));headers.set('Accept-Ranges','bytes');return new Response(bytes.slice(start,end+1),{status:206,headers})}
  if(hit)return hit;if(name!==CACHE)return new Response('This pond keeps its previous build until a safe reload.',{status:503,headers:{'Cache-Control':'no-store'}});return fetch(event.request)
 })());
});
'''.replace('VERSION',json.dumps(version)).replace('URLS',json.dumps(urls))
(root/'sw.js').write_text(script)
(root/'reports/precache.json').write_text(json.dumps({'cache':version,'urls':urls},indent=2))
print(version,len(urls),'URLs')

if '--bump-cache' in sys.argv:
 hold.write_text(json.dumps({'holdCache':True,'preparedLocalOnly':True,'published':False,'cache':version,'sw_sha256':hashlib.sha256((root/'sw.js').read_bytes()).hexdigest(),'precache_sha256':hashlib.sha256((root/'reports/precache.json').read_bytes()).hexdigest()},indent=2)+'\n')
